#include "../network/socket.hpp"
#include "../store/session_store.hpp"
#include "noise_state.hpp"
#include <array>
#include <cstdint>
#include <memory>
#include <vector>

namespace WAWP::Protocol {

class Handshake {
public:
	Handshake(Network::Socket& socket, std::shared_ptr<Store::SessionStore>& store);
	~Handshake() = default;

	SessionKeys start();

private:
	void frame_and_send(const std::vector<uint8_t>& payload);
	std::vector<uint8_t> read_frame();

	Network::Socket& m_socket;
	std::shared_ptr<Store::SessionStore>& m_store;

	NoiseState m_noise_state { };

	bool m_is_start = true;

	static constexpr std::array<uint8_t, 4> m_prologue { 0x57, 0x41, 0x06, 0x03 };

	// "Noise_XX_25519_AESGCM_SHA256\0\0\0\0"
	static constexpr std::array<uint8_t, 32> m_noise_xx {
		0x4E,
		0x6F,
		0x69,
		0x73,
		0x65,
		0x5F,
		0x58,
		0x58,
		0x5F,
		0x32,
		0x35,
		0x35,
		0x31,
		0x39,
		0x5F,
		0x41,
		0x45,
		0x53,
		0x47,
		0x43,
		0x4D,
		0x5F,
		0x53,
		0x48,
		0x41,
		0x32,
		0x35,
		0x36,
		0x00,
		0x00,
		0x00,
		0x00,
	};
};

}

