package WAWebProto;

message HandshakeMessage {
	optional HandshakeMessage.ClientHello clientHello = 2;
	optional HandshakeMessage.ServerHello serverHello = 3;
	optional HandshakeMessage.ClientFinish clientFinish = 4;

	message ClientHello {
		optional bytes ephemeral = 1;
	}

	message ServerHello {
		optional bytes ephemeral = 1;
		optional bytes static = 2;
		optional bytes payload = 3;
	}

	message ClientFinish {
		optional bytes static = 1;
		optional bytes payload = 2;
	}
}

message ClientPayload {
	optional bool passive = 3;
	optional ClientPayload.UserAgent userAgent = 5;
	optional ClientPayload.WebInfo webInfo = 6;
	optional ClientPayload.ConnectType connectType = 12;
	optional ClientPayload.ConnectReason connectReason = 13;
	optional ClientPayload.DevicePairingRegistrationData devicePairingData = 19;
	optional bool pull = 33;

	message UserAgent {
		optional ClientPayload.UserAgent.Platform platform = 1;
		optional ClientPayload.UserAgent.AppVersion appVersion = 2;
		optional string mcc = 3;
		optional string mnc = 4;
		optional string osVersion = 5;
		optional string manufacturer = 6;
		optional string device = 7;
