#include "src/client/client.hpp"
#include "src/client/config.hpp"
#include "src/network/version_fetcher.hpp"
#include "src/store/memory_session_store.hpp"
#include <boost/asio/io_context.hpp>
#include <cstdlib>
#include <iostream>
#include <memory>

int main() {
	auto io_context = boost::asio::io_context { };

	auto wa_version = WAWP::Network::VersionFetcher::fetch_current();

	std::cout << wa_version.full_base << "\n";

	WAWP::ClientConfig config { .version = wa_version, .store = std::make_shared<WAWP::Store::MemorySessionStore>() };

	WAWP::Client client { io_context, config };

	client.connect();

	io_context.run();

	return EXIT_SUCCESS;
}

