// Convert Curve25519 public key (little-endian) to Ed25519 public key
// using XEdDSA: y = (u-1)/(u+1) mod p, sign = 0
std::array<uint8_t,32> c25519_to_ed25519(const std::array<uint8_t,32>& u_le) {
    // Flip to big-endian for OpenSSL BN
    uint8_t u_be[32];
    for (int i = 0; i < 32; i++) u_be[i] = u_le[31-i];

    BN_CTX* ctx = BN_CTX_new();
    BIGNUM *p = BN_new(), *u = BN_new(), *one = BN_new();
    BIGNUM *num = BN_new(), *den = BN_new(), *inv = BN_new(), *y = BN_new();

    // p = 2^255 - 19
    BN_zero(p); BN_set_bit(p, 255); BN_sub_word(p, 19);
    BN_one(one);
    BN_bin2bn(u_be, 32, u);

    // num = u - 1,  den = u + 1
    BN_mod_sub(num, u, one, p, ctx);
    BN_mod_add(den, u, one, p, ctx);

    // inv = den^(p-2) mod p  (Fermat)
    BIGNUM* exp = BN_dup(p); BN_sub_word(exp, 2);
    BN_mod_exp(inv, den, exp, p, ctx);

    // y = num * inv mod p
    BN_mod_mul(y, num, inv, p, ctx);

    // y → little-endian bytes, sign bit = 0
    std::array<uint8_t,32> out = {};
    uint8_t y_be[32] = {};
    BN_bn2binpad(y, y_be, 32);
    for (int i = 0; i < 32; i++) out[i] = y_be[31-i];
    out[31] &= 0x7F;  // force positive x per XEdDSA spec

    BN_free(p); BN_free(u); BN_free(one); BN_free(num);
    BN_free(den); BN_free(inv); BN_free(y); BN_free(exp);
    BN_CTX_free(ctx);
    return out;
}

int main() {
    sodium_init();

    auto ed_pub = c25519_to_ed25519(WA_KEY);

    printf("Ed25519 key (from XEdDSA conversion): ");
    for (auto b : ed_pub) printf("%02x", b);
    printf("\n");

    int r = crypto_sign_ed25519_verify_detached(
