bool xeddsa_verify(
    const std::array<uint8_t, 32>& curve25519_pub,
    const uint8_t* message, size_t message_len,
    const uint8_t* signature) {
	// Convert Curve25519 key (little-endian) to Ed25519 public key via:
	//   y = (u - 1) * modinv(u + 1, p) mod p,  sign bit = 0
	uint8_t u_be[32];
	for (int i = 0; i < 32; i++) u_be[i] = curve25519_pub[31 - i];

	BN_CTX* ctx = BN_CTX_new();
	BIGNUM *p = BN_new(), *u = BN_new(), *one = BN_new();
	BIGNUM *num = BN_new(), *den = BN_new(), *inv = BN_new(), *y = BN_new(), *exp = nullptr;

	BN_zero(p); BN_set_bit(p, 255); BN_sub_word(p, 19);
	BN_one(one);
	BN_bin2bn(u_be, 32, u);

	BN_mod_sub(num, u, one, p, ctx);
	BN_mod_add(den, u, one, p, ctx);

	exp = BN_dup(p); BN_sub_word(exp, 2);
	BN_mod_exp(inv, den, exp, p, ctx);
	BN_mod_mul(y, num, inv, p, ctx);

	std::array<uint8_t, 32> ed_pub = {};
	uint8_t y_be[32] = {};
	BN_bn2binpad(y, y_be, 32);
	for (int i = 0; i < 32; i++) ed_pub[i] = y_be[31 - i];
	ed_pub[31] &= 0x7F;

	BN_free(p); BN_free(u); BN_free(one);
	BN_free(num); BN_free(den); BN_free(inv); BN_free(y); BN_free(exp);
	BN_CTX_free(ctx);

	return crypto_sign_ed25519_verify_detached(
	    signature, message, message_len, ed_pub.data()) == 0;
}

